import fs from "node:fs";
import path from "node:path";
import yaml from "js-yaml";

const load = (p) => yaml.load(fs.readFileSync(p, "utf8"));

const oldDir = "/private/tmp/claude-501/-Users-ungood-workspaces-personal-isthmia/a6dad625-1595-476c-bdd5-0978bc95edb7/scratchpad/old";
const wt = "/Users/ungood/workspaces/personal/isthmia/.claude/worktrees/program-catalog/packages";

const before = fs.readdirSync(oldDir).map((f) => load(path.join(oldDir, f)));
const after = fs
  .readdirSync(wt)
  .filter((d) => fs.existsSync(path.join(wt, d, "schema.yaml")))
  .map((d) => load(path.join(wt, d, "schema.yaml")));

console.log("schema files: before", before.length, "after", after.length);

// mergeSchemas: concatenate collections/fields/relations across packages.
const merge = (schemas) => ({
  collections: schemas.flatMap((s) => s.collections ?? []),
  fields: schemas.flatMap((s) => s.fields ?? []),
  relations: schemas.flatMap((s) => s.relations ?? []),
});

const key = {
  collections: (e) => e.collection,
  fields: (e) => `${e.collection}.${e.field}`,
  relations: (e) => `${e.collection}.${e.field}`,
};

const a = merge(before);
const b = merge(after);

let bad = 0;
for (const block of ["collections", "fields", "relations"]) {
  const ma = new Map(a[block].map((e) => [key[block](e), e]));
  const mb = new Map(b[block].map((e) => [key[block](e), e]));
  if (ma.size !== a[block].length) console.log(`  !! duplicate keys in BEFORE ${block}`);
  if (mb.size !== b[block].length) console.log(`  !! duplicate keys in AFTER ${block}`);

  const missing = [...ma.keys()].filter((k) => !mb.has(k));
  const extra = [...mb.keys()].filter((k) => !ma.has(k));
  const differing = [...ma.keys()]
    .filter((k) => mb.has(k))
    .filter((k) => JSON.stringify(ma.get(k)) !== JSON.stringify(mb.get(k)));

  console.log(
    `${block}: ${ma.size} -> ${mb.size} | missing ${missing.length} | extra ${extra.length} | differing ${differing.length}`,
  );
  for (const k of [...missing, ...extra, ...differing].slice(0, 20)) console.log("   *", k);
  bad += missing.length + extra.length + differing.length;
}

// systemFields moved file-to-file, not through the merge.
const sfBefore = before.find((s) => s.systemFields)?.systemFields;
const sfAfter = after.find((s) => s.systemFields)?.systemFields;
console.log(
  "systemFields identical:",
  JSON.stringify(sfBefore) === JSON.stringify(sfAfter),
  `(${sfBefore?.length ?? 0} entries)`,
);

